export function useTableVirtualization({ bodyRef, bodyStyle, canDeferOffscreenCellContent, columnDragActive, draggingRowIndex, getIsCustomRow, getIsGroupHeaderRow, rows, rowVirtualizer, table, }) {
    const { bodyRows, controller, directDomUpdates, resolveDeferredRow, runtime, virtualizationCoverage, } = useAdaptiveTableVirtualization({
        draggingRowIndex,
        getIsCustomRow,
        getIsGroupHeaderRow,
        rows,
        rowVirtualizer,
    });
    const { bodyElementRef, resolvedBodyRef } = useVirtualizedTableBodyRef({
        bodyRef,
        directDomUpdates,
        rowVirtualizer,
        runtime,
    });
    const leftColumns = table.getLeftVisibleLeafColumns();
    const centerColumns = table.getCenterVisibleLeafColumns();
    const rightColumns = table.getRightVisibleLeafColumns();
    const { canStageCellContent, forceCellContentHydration, immediateCellContentColumnIds, scheduleCellContentHydration, } = useOffscreenCellContent({
        bodyElementRef,
        columnDragActive,
        enabled: isOffscreenCellContentDeferralEnabled(Boolean(canDeferOffscreenCellContent), Boolean(controller), directDomUpdates),
        scrollElement: rowVirtualizer?.scrollElement,
        centerColumns,
        leftColumns,
        rightColumns,
    });
