                    }
                    : rowRenderVersion,
                virtualItem,
            },
        };
    }, [
        canDeferOffscreenCellContent,
        canStageCellContent,
        controller,
        directDomUpdates,
        forceCellContentHydration,
        getIsCustomRow,
        getIsGroupHeaderRow,
        immediateCellContentColumnIds,
        resolveDeferredRow,
        rowRenderVersion,
        rowVirtualizer,
        scheduleCellContentHydration,
